class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        # Add vertex v to the adjacency list of vertex u
        if u not in self.graph:
            self.graph[u] = []
        if v not in self.graph:
            self.graph[v] = []
        self.graph[u].append(v)
        self.graph[v].append(u)

