import heapq

def dijkstra(graph, start):
    """
    Dijkstra's shortest path algorithm.

    :param graph: A dictionary representing the graph where keys are nodes and values are dictionaries of neighboring nodes and edge weights.
    :param start: The starting node.
    :return: A dictionary of shortest path lengths from the start node to all other nodes, and the shortest path to each node.
    """
    if not graph:
        return {}

    # Initialize distances to all nodes as infinity except for the start node which is 0
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0

    # Priority queue to process nodes based on shortest distance
    priority_queue = [(0, start)]

    while priority_queue:
        # Pop the node with the smallest distance
        current_distance, current_node = heapq.heappop(priority_queue)

        # If the current distance is greater than the recorded distance, skip this node
        if current_distance > distances[current_node]:
            continue

        # Explore neighboring nodes
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            # If a shorter path is found, update the distance and push the neighbor to the priority queue
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    # Create a dictionary to store the shortest path to each node
    shortest_paths = {node: [] for node in graph}
    for node in graph:
        if distances[node] != float('infinity'):
            shortest_paths[node] = shortest_paths[distances.index(distances[node])]

    return distances, shortest_paths

